// Shared domain types for the secret rotation validator.

export interface SecretConfig {
  name: string;
  lastRotated: string; // ISO date string, e.g. "2026-01-01"
  rotationPolicyDays: number;
  requiredByServices: string[];
}

export interface SecretsFile {
  secrets: SecretConfig[];
}

export type Urgency = "expired" | "warning" | "ok";

export interface SecretStatus {
  name: string;
  lastRotated: string;
  rotationPolicyDays: number;
  requiredByServices: string[];
  expiresOn: string; // ISO date string
  daysUntilExpiry: number; // negative if already expired
  urgency: Urgency;
}

export interface RotationReport {
  generatedAt: string;
  warningWindowDays: number;
  expired: SecretStatus[];
  warning: SecretStatus[];
  ok: SecretStatus[];
