import { describe, expect, test } from "bun:test";
import { computeReport, formatMarkdown, formatJson, loadSecretsFile } from "./validator";
import type { SecretsFile } from "./types";

describe("computeReport", () => {
  const now = new Date("2026-07-01T00:00:00.000Z");

  test("classifies an already-expired secret", () => {
    const config: SecretsFile = {
      warningWindowDays: 7,
      secrets: [
        {
          name: "DATABASE_PASSWORD",
          lastRotated: "2025-01-01",
          rotationPolicyDays: 90,
          requiredBy: ["api-service"],
        },
      ],
    };
    const report = computeReport(config, now);
    expect(report.expired.length).toBe(1);
    expect(report.expired[0].name).toBe("DATABASE_PASSWORD");
    expect(report.expired[0].urgency).toBe("expired");
    expect(report.warning.length).toBe(0);
    expect(report.ok.length).toBe(0);
  });

  test("classifies a secret expiring within the warning window", () => {
    const config: SecretsFile = {
      warningWindowDays: 7,
      secrets: [
        {
          name: "JWT_SIGNING_KEY",
          lastRotated: "2026-06-05",
          rotationPolicyDays: 30,
          requiredBy: ["auth-service"],
        },
      ],
    };
    // expires 2026-07-05, 4 days from "now" -> within 7-day window
    const report = computeReport(config, now);
    expect(report.warning.length).toBe(1);
    expect(report.warning[0].name).toBe("JWT_SIGNING_KEY");
    expect(report.warning[0].daysUntilExpiry).toBe(4);
  });

  test("classifies a secret well within policy as ok", () => {
    const config: SecretsFile = {
      warningWindowDays: 7,
      secrets: [
        {
          name: "API_KEY_STRIPE",
          lastRotated: "2026-06-25",
          rotationPolicyDays: 90,
          requiredBy: ["billing-service"],
        },
      ],
    };
    const report = computeReport(config, now);
    expect(report.ok.length).toBe(1);
    expect(report.ok[0].urgency).toBe("ok");
  });

  test("defaults warningWindowDays to 14 when not provided", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "SOME_SECRET",
          lastRotated: "2026-06-20",
          rotationPolicyDays: 30,
          requiredBy: [],
        },
      ],
    };
    // expires 2026-07-20, 19 days out -> beyond default 14-day window -> ok
    const report = computeReport(config, now);
    expect(report.ok.length).toBe(1);
  });

  test("handles an empty secrets list", () => {
    const config: SecretsFile = { secrets: [], warningWindowDays: 7 };
    const report = computeReport(config, now);
    expect(report.expired.length).toBe(0);
    expect(report.warning.length).toBe(0);
    expect(report.ok.length).toBe(0);
  });

  test("throws a meaningful error for invalid rotation policy", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "BAD_SECRET",
          lastRotated: "2026-06-20",
          rotationPolicyDays: -5,
          requiredBy: [],
        },
      ],
    };
    expect(() => computeReport(config, now)).toThrow(/rotationPolicyDays/);
  });

  test("throws a meaningful error for invalid date format", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "BAD_DATE",
          lastRotated: "not-a-date",
          rotationPolicyDays: 30,
          requiredBy: [],
        },
      ],
    };
    expect(() => computeReport(config, now)).toThrow(/lastRotated/);
  });
});

describe("formatMarkdown", () => {
  test("produces a markdown report with sections for each urgency", () => {
    const config: SecretsFile = {
      warningWindowDays: 7,
      secrets: [
        { name: "EXPIRED_ONE", lastRotated: "2025-01-01", rotationPolicyDays: 30, requiredBy: ["svc-a"] },
        { name: "WARN_ONE", lastRotated: "2026-06-28", rotationPolicyDays: 5, requiredBy: ["svc-b"] },
        { name: "OK_ONE", lastRotated: "2026-06-30", rotationPolicyDays: 365, requiredBy: ["svc-c"] },
      ],
    };
    const now = new Date("2026-07-01T00:00:00.000Z");
    const report = computeReport(config, now);
    const md = formatMarkdown(report);
    expect(md).toContain("# Secret Rotation Report");
    expect(md).toContain("## Expired");
    expect(md).toContain("EXPIRED_ONE");
    expect(md).toContain("## Warning");
    expect(md).toContain("WARN_ONE");
    expect(md).toContain("## OK");
    expect(md).toContain("OK_ONE");
    expect(md).toContain("svc-a");
  });
});

describe("formatJson", () => {
  test("produces valid JSON matching the report shape", () => {
    const config: SecretsFile = {
      warningWindowDays: 7,
      secrets: [
        { name: "ONLY_SECRET", lastRotated: "2025-01-01", rotationPolicyDays: 30, requiredBy: ["svc-a"] },
      ],
    };
    const now = new Date("2026-07-01T00:00:00.000Z");
    const report = computeReport(config, now);
    const json = formatJson(report);
    const parsed = JSON.parse(json);
    expect(parsed.expired[0].name).toBe("ONLY_SECRET");
    expect(parsed.warningWindowDays).toBe(7);
  });
});

describe("loadSecretsFile", () => {
  test("loads and parses the basic fixture", async () => {
    const config = await loadSecretsFile("./fixtures/secrets-basic.json");
    expect(config.secrets.length).toBe(3);
    expect(config.warningWindowDays).toBe(7);
  });

  test("throws for a missing file", async () => {
    await expect(loadSecretsFile("./fixtures/does-not-exist.json")).rejects.toThrow();
  });
