// Piece 1: date/expiry calculation logic.
describe("calculateExpiry", () => {
  const now = new Date("2026-07-01T00:00:00.000Z");

  test("computes expiresOn as lastRotated + rotationPolicyDays", () => {
    const secret: SecretConfig = {
      name: "db-password",
      lastRotated: "2026-06-01",
      rotationPolicyDays: 30,
      requiredByServices: ["api"],
    };
    const status = calculateExpiry(secret, now);
    expect(status.expiresOn).toBe("2026-07-01");
  });

  test("marks a secret as expired when past its expiry date", () => {
    const secret: SecretConfig = {
      name: "api-key",
      lastRotated: "2026-01-01",
      rotationPolicyDays: 30,
      requiredByServices: ["gateway"],
    };
    const status = calculateExpiry(secret, now);
    expect(status.urgency).toBe("expired");
    expect(status.daysUntilExpiry).toBeLessThan(0);
  });

  test("marks a secret as ok when far from expiry", () => {
    const secret: SecretConfig = {
      name: "webhook-secret",
      lastRotated: "2026-06-30",
      rotationPolicyDays: 365,
      requiredByServices: ["webhooks"],
    };
    const status = calculateExpiry(secret, now, 7);
    expect(status.urgency).toBe("ok");
    expect(status.daysUntilExpiry).toBeGreaterThan(7);
  });

  test("throws on invalid lastRotated date", () => {
    const secret: SecretConfig = {
      name: "bad-date",
      lastRotated: "not-a-date",
      rotationPolicyDays: 30,
      requiredByServices: [],
    };
    expect(() => calculateExpiry(secret, now)).toThrow(/invalid.*date/i);
  });

  test("throws on negative rotation policy days", () => {
    const secret: SecretConfig = {
      name: "negative-policy",
      lastRotated: "2026-01-01",
      rotationPolicyDays: -5,
      requiredByServices: [],
    };
    expect(() => calculateExpiry(secret, now)).toThrow(/rotationPolicyDays/);
  });

  test("throws on missing name field", () => {
    const secret = {
      name: "",
      lastRotated: "2026-01-01",
      rotationPolicyDays: 30,
      requiredByServices: [],
    } as SecretConfig;
    expect(() => calculateExpiry(secret, now)).toThrow(/name/i);
  });
});

import type { SecretConfig, SecretStatus, Urgency } from "./types";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function toDateOnlyString(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/**
 * Compute the rotation status of a single secret relative to `now`.
 * Throws descriptive errors for malformed input rather than silently
 * producing garbage results.
 */
export function calculateExpiry(
  secret: SecretConfig,
  now: Date = new Date(),
  warningWindowDays = 14
): SecretStatus {
  if (!secret.name || secret.name.trim() === "") {
    throw new Error("Secret is missing a required 'name' field");
  }
  if (!secret.lastRotated || Number.isNaN(Date.parse(secret.lastRotated))) {
    throw new Error(
      `Secret "${secret.name}" has an invalid lastRotated date: ${JSON.stringify(secret.lastRotated)}`
    );
  }
  if (
    typeof secret.rotationPolicyDays !== "number" ||
    !Number.isFinite(secret.rotationPolicyDays) ||
    secret.rotationPolicyDays < 0
  ) {
    throw new Error(
      `Secret "${secret.name}" has an invalid rotationPolicyDays value (must be a non-negative number): ${secret.rotationPolicyDays}`
    );
  }
  if (!Array.isArray(secret.requiredByServices)) {
    throw new Error(
      `Secret "${secret.name}" is missing a requiredByServices array`
    );
  }

  const lastRotatedDate = new Date(secret.lastRotated + "T00:00:00.000Z");
  const expiresOnDate = new Date(
    lastRotatedDate.getTime() + secret.rotationPolicyDays * MS_PER_DAY
  );

  const nowMidnight = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate())
  );
  const daysUntilExpiry = Math.round(
    (expiresOnDate.getTime() - nowMidnight.getTime()) / MS_PER_DAY
  );

  let urgency: Urgency;
  if (daysUntilExpiry < 0) {
    urgency = "expired";
  } else if (daysUntilExpiry <= warningWindowDays) {
    urgency = "warning";
  } else {
    urgency = "ok";
  }

  return {
    name: secret.name,
    lastRotated: secret.lastRotated,
    rotationPolicyDays: secret.rotationPolicyDays,
    requiredByServices: secret.requiredByServices,
    expiresOn: toDateOnlyString(expiresOnDate),
    daysUntilExpiry,
    urgency,
  };
}

// Secret Rotation Validator
//
// Given a configuration of secrets (name, last-rotated date, rotation policy
// in days, required-by services), determines which secrets are expired,
// expiring soon (within a configurable warning window), or ok. Produces a
// report in markdown or JSON format.

import type {
  RotationReport,
  SecretConfig,
  SecretStatus,
  SecretsFile,
  Urgency,
} from "./types";

const DEFAULT_WARNING_WINDOW_DAYS = 14;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Parses an ISO date string (YYYY-MM-DD) into a UTC Date, throwing a
 * meaningful error if the string is not a valid date. */
function parseIsoDate(fieldName: string, value: string): Date {
  const isoDatePattern = /^\d{4}-\d{2}-\d{2}$/;
  if (!isoDatePattern.test(value)) {
    throw new Error(
      `Invalid ${fieldName}: "${value}" is not a valid ISO date (expected YYYY-MM-DD)`,
    );
  }
  const date = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid ${fieldName}: "${value}" could not be parsed as a date`);
  }
  return date;
}

function toIsoDateString(date: Date): string {
  return date.toISOString().slice(0, 10);
}

/** Computes the rotation status for a single secret relative to `now`. */
function computeSecretStatus(
  secret: SecretConfig,
  now: Date,
  warningWindowDays: number,
): SecretStatus {
  if (!secret.name || secret.name.trim() === "") {
    throw new Error("Invalid secret: missing required field 'name'");
  }
  if (!Number.isFinite(secret.rotationPolicyDays) || secret.rotationPolicyDays <= 0) {
    throw new Error(
      `Invalid secret "${secret.name}": rotationPolicyDays must be a positive number, got ${secret.rotationPolicyDays}`,
    );
  }

  const lastRotated = parseIsoDate(`lastRotated for secret "${secret.name}"`, secret.lastRotated);
  const expiresOn = new Date(lastRotated.getTime() + secret.rotationPolicyDays * MS_PER_DAY);
  const daysUntilExpiry = Math.floor((expiresOn.getTime() - now.getTime()) / MS_PER_DAY);

  let urgency: Urgency;
  if (daysUntilExpiry <= 0) {
    urgency = "expired";
  } else if (daysUntilExpiry <= warningWindowDays) {
    urgency = "warning";
  } else {
    urgency = "ok";
  }

  return {
    name: secret.name,
    lastRotated: secret.lastRotated,
    rotationPolicyDays: secret.rotationPolicyDays,
    requiredBy: secret.requiredBy ?? [],
    expiresOn: toIsoDateString(expiresOn),
    daysUntilExpiry,
    urgency,
  };
}

/** Computes a full rotation report for a set of secrets, grouped by urgency. */
export function computeReport(config: SecretsFile, now: Date = new Date()): RotationReport {
  const warningWindowDays = config.warningWindowDays ?? DEFAULT_WARNING_WINDOW_DAYS;

  const statuses = config.secrets.map((secret) =>
    computeSecretStatus(secret, now, warningWindowDays),
  );

  const report: RotationReport = {
    generatedAt: now.toISOString(),
    warningWindowDays,
    expired: statuses.filter((s) => s.urgency === "expired"),
    warning: statuses.filter((s) => s.urgency === "warning"),
    ok: statuses.filter((s) => s.urgency === "ok"),
  };

  // Sort each group by urgency (soonest expiry first) for readability.
  const byExpiry = (a: SecretStatus, b: SecretStatus) => a.daysUntilExpiry - b.daysUntilExpiry;
  report.expired.sort(byExpiry);
  report.warning.sort(byExpiry);
  report.ok.sort(byExpiry);

  return report;
}

function formatSecretRow(s: SecretStatus): string {
  const required = s.requiredBy.length > 0 ? s.requiredBy.join(", ") : "(none)";
  return `| ${s.name} | ${s.lastRotated} | ${s.expiresOn} | ${s.daysUntilExpiry} | ${required} |`;
}

function formatSection(title: string, statuses: SecretStatus[]): string {
  const lines = [`## ${title}`, ""];
  if (statuses.length === 0) {
    lines.push("_None_", "");
    return lines.join("\n");
  }
  lines.push(
    "| Secret | Last Rotated | Expires On | Days Until Expiry | Required By |",
    "|---|---|---|---|---|",
  );
  for (const s of statuses) {
    lines.push(formatSecretRow(s));
  }
  lines.push("");
  return lines.join("\n");
}

/** Renders a RotationReport as a GitHub-flavored markdown document. */
export function formatMarkdown(report: RotationReport): string {
  const lines = [
    "# Secret Rotation Report",
    "",
    `Generated: ${report.generatedAt}`,
    `Warning window: ${report.warningWindowDays} day(s)`,
    "",
    formatSection("Expired", report.expired),
    formatSection("Warning", report.warning),
    formatSection("OK", report.ok),
  ];
  return lines.join("\n").trimEnd() + "\n";
}

/** Renders a RotationReport as pretty-printed JSON. */
export function formatJson(report: RotationReport): string {
  return JSON.stringify(report, null, 2);
}

/** Loads and parses a secrets configuration file from disk. */
export async function loadSecretsFile(path: string): Promise<SecretsFile> {
  const file = Bun.file(path);
  if (!(await file.exists())) {
    throw new Error(`Secrets file not found: ${path}`);
  }
  let raw: unknown;
  try {
    raw = await file.json();
  } catch (err) {
    throw new Error(`Failed to parse secrets file "${path}" as JSON: ${(err as Error).message}`);
  }
  const parsed = raw as Partial<SecretsFile>;
  if (!parsed || !Array.isArray(parsed.secrets)) {
    throw new Error(`Invalid secrets file "${path}": missing or invalid "secrets" array`);
  }
  return parsed as SecretsFile;
}

