import type { SecretsFile } from "./types";

// Piece 2: grouping secrets by urgency and assembling a full report.
describe("generateReport", () => {
  const now = new Date("2026-07-01T00:00:00.000Z");

  test("groups secrets into expired, warning, ok buckets", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "expired-secret",
          lastRotated: "2026-01-01",
          rotationPolicyDays: 30,
          requiredByServices: ["svc-a"],
        },
        {
          name: "warning-secret",
          lastRotated: "2026-06-20",
          rotationPolicyDays: 15,
          requiredByServices: ["svc-b"],
        },
        {
          name: "ok-secret",
          lastRotated: "2026-06-30",
          rotationPolicyDays: 365,
          requiredByServices: ["svc-c"],
        },
      ],
    };
    const report = generateReport(config, { now, warningWindowDays: 7 });
    expect(report.expired.length).toBe(1);
    expect(report.expired[0]?.name).toBe("expired-secret");
    expect(report.warning.length).toBe(1);
    expect(report.warning[0]?.name).toBe("warning-secret");
    expect(report.ok.length).toBe(1);
    expect(report.ok[0]?.name).toBe("ok-secret");
    expect(report.warningWindowDays).toBe(7);
  });

  test("throws a descriptive error when secrets array is missing", () => {
    // @ts-expect-error intentionally malformed input for error-path testing
    expect(() => generateReport({}, { now })).toThrow(/secrets/i);
  });

  test("throws a descriptive error when secrets is not an array", () => {
    // @ts-expect-error intentionally malformed input
    expect(() => generateReport({ secrets: "nope" }, { now })).toThrow(/secrets/i);
  });

  test("propagates per-secret validation errors with context", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "bad",
          lastRotated: "not-a-date",
          rotationPolicyDays: 30,
          requiredByServices: [],
        },
      ],
    };
    expect(() => generateReport(config, { now })).toThrow(/invalid.*date/i);
  });

  test("sorts within each bucket by soonest expiry first", () => {
    const config: SecretsFile = {
      secrets: [
        {
          name: "expires-later",
          lastRotated: "2026-01-01",
          rotationPolicyDays: 30,
          requiredByServices: [],
        },
        {
          name: "expires-sooner",
          lastRotated: "2025-12-01",
          rotationPolicyDays: 30,
          requiredByServices: [],
        },
      ],
    };
    const report = generateReport(config, { now });
    expect(report.expired.map((s) => s.name)).toEqual([
      "expires-sooner",
      "expires-later",
    ]);
  });
});

#!/usr/bin/env bun
// CLI entrypoint for the Secret Rotation Validator.
//
// Usage:
//   bun run app.ts --input <secrets.json> [--format markdown|json] [--now <ISO date>] [--output <file>]

import { computeReport, formatJson, formatMarkdown, loadSecretsFile } from "./validator";

interface CliArgs {
  input: string;
  format: "markdown" | "json";
  now?: string;
  output?: string;
}

function parseArgs(argv: string[]): CliArgs {
  let input: string | undefined;
  let format: "markdown" | "json" = "markdown";
  let now: string | undefined;
  let output: string | undefined;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    switch (arg) {
      case "--input":
        input = argv[++i];
        break;
      case "--format":
        {
          const value = argv[++i];
          if (value !== "markdown" && value !== "json") {
            throw new Error(`Invalid --format "${value}": expected "markdown" or "json"`);
          }
          format = value;
        }
        break;
      case "--now":
        now = argv[++i];
        break;
      case "--output":
        output = argv[++i];
        break;
      default:
        throw new Error(`Unknown argument: ${arg}`);
    }
  }

  if (!input) {
    throw new Error("Missing required argument: --input <secrets.json>");
  }

  return { input, format, now, output };
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));

  const config = await loadSecretsFile(args.input);
  const now = args.now ? new Date(args.now) : new Date();
  if (Number.isNaN(now.getTime())) {
    throw new Error(`Invalid --now value: "${args.now}"`);
  }

  const report = computeReport(config, now);
  const rendered = args.format === "json" ? formatJson(report) : formatMarkdown(report);

  if (args.output) {
    await Bun.write(args.output, rendered);
  } else {
    console.log(rendered);
  }

  // Exit non-zero if any secret is expired, so CI can fail the build.
  if (report.expired.length > 0) {
    console.error(`\n${report.expired.length} secret(s) have expired rotation policies.`);
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(`Error: ${(err as Error).message}`);
  process.exit(1);
});

import { calculateExpiry } from "./expiry";
import type { RotationReport, SecretsFile, SecretStatus } from "./types";

export interface GenerateReportOptions {
  now?: Date;
  warningWindowDays?: number;
}

/**
 * Validate a secrets config, compute expiry status for every secret,
 * and group the results into expired/warning/ok buckets sorted by
 * soonest expiry first (most urgent at the top of each bucket).
 */
export function generateReport(
  config: SecretsFile,
  options: GenerateReportOptions = {}
): RotationReport {
  const now = options.now ?? new Date();
  const warningWindowDays = options.warningWindowDays ?? 14;

  if (!config || !Array.isArray(config.secrets)) {
    throw new Error(
      "Invalid configuration: expected a 'secrets' array at the top level"
    );
  }

  const statuses: SecretStatus[] = config.secrets.map((secret) =>
    calculateExpiry(secret, now, warningWindowDays)
  );

  const byUrgencySort = (a: SecretStatus, b: SecretStatus) =>
    a.daysUntilExpiry - b.daysUntilExpiry;

  const expired = statuses
    .filter((s) => s.urgency === "expired")
    .sort(byUrgencySort);
  const warning = statuses
    .filter((s) => s.urgency === "warning")
    .sort(byUrgencySort);
  const ok = statuses.filter((s) => s.urgency === "ok").sort(byUrgencySort);

  return {
    generatedAt: now.toISOString(),
    warningWindowDays,
    expired,
    warning,
    ok,
  };
}

