import type { RotationReport, SecretStatus } from "./types";

export function formatJson(report: RotationReport): string {
  return JSON.stringify(report, null, 2);
}

function table(statuses: SecretStatus[]): string {
  if (statuses.length === 0) {
    return "_None_\n";
  }
  const header =
    "| Name | Last Rotated | Expires On | Days Until Expiry | Required By |\n" +
    "| --- | --- | --- | --- | --- |\n";
  const rows = statuses
    .map(
      (s) =>
        `| ${s.name} | ${s.lastRotated} | ${s.expiresOn} | ${s.daysUntilExpiry} | ${s.requiredByServices.join(", ")} |`
    )
    .join("\n");
  return header + rows + "\n";
}

export function formatMarkdown(report: RotationReport): string {
  const lines: string[] = [];
  lines.push("# Secret Rotation Report");
  lines.push("");
  lines.push(`Generated at: ${report.generatedAt}`);
  lines.push(`Warning window: ${report.warningWindowDays} days`);
  lines.push("");
  lines.push("## Expired");
  lines.push("");
  lines.push(table(report.expired));
  lines.push("## Warning");
  lines.push("");
  lines.push(table(report.warning));
  lines.push("## OK");
  lines.push("");
  lines.push(table(report.ok));
  return lines.join("\n");
}

