async function setupTempRepo(): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), "secret-rotation-act-"));
  for (const file of PROJECT_FILES) {
    const src = join(import.meta.dir, file);
    if (await Bun.file(src).exists().catch(() => false) || file === "fixtures" || file === ".github") {
      try {
        await cp(src, join(dir, file), { recursive: true });
      } catch {
        // optional files (e.g. package.json may not exist) are skipped
      }
    }
  }
  await runCommand(["git", "init"], dir);
  await runCommand(["git", "config", "user.email", "test@example.com"], dir);
  await runCommand(["git", "config", "user.name", "Test"], dir);
  await runCommand(["git", "add", "-A"], dir);
  await runCommand(["git", "commit", "-m", "test"], dir);
